import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times. Return the result on success.
    If all attempts fail, re‑raise the last exception without sleeping after it.
    """
    attempt = 1
    while attempt <= max_attempts:
        try:
            return fn()
        except Exception as exc:
            if attempt == max_attempts:
                # Final attempt failed – re‑raise without sleeping
                raise
            # Sleep before the next retry
            time.sleep(0.01 * attempt)
            attempt += 1
