def is_balanced(s):
    """
    Return True if the string s contains only correctly nested and matched
    parentheses, square brackets, and curly braces. Otherwise return False.
    """
    # Mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}
    # Set of opening brackets for quick lookup
    opens = set(pairs.values())

    stack = []

    for c in s:
        if c in opens:
            stack.append(c)
        elif c in pairs:
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()
        else:
            # Ignore any other characters
            continue

    return not stack
