def parse_bool(value):
    """
    Convert a value to a boolean.

    Accepts:
    - bool: returned unchanged.
    - int: 0 -> False, any non‑zero -> True.
    - str: case‑insensitive matches of "true", "yes", "1" -> True;
           matches of "false", "no", "0" -> False.
    Raises:
    - ValueError for any other string.
    """
    if isinstance(value, bool):
        return value

    if isinstance(value, int):
        return bool(value)

    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in {"true", "yes", "1"}:
            return True
        if lowered in {"false", "no", "0"}:
            return False
        raise ValueError(f"Invalid boolean string: {value!r}")

    raise TypeError(f"Unsupported type for parse_bool: {type(value).__name__}")
